import{_ as s,c as t,o as n,j as o,Y as i,t as r}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"nscd | x-cmd man (man8) | name service cache daemon","titleTemplate":false,"description":"x-cmd man (man8 Manual Page) | nscd - name service cache daemon","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nscd | x-cmd man (man8) | name service cache daemon"}],["meta",{"name":"og:description","content":"x-cmd man (man8 Manual Page) | nscd - name service cache daemon"}]]},"headers":[],"params":{"isMan":true,"man":"nscd","category":"man8","desc":"name service cache daemon"},"relativePath":"man8/nscd.md","filePath":"man8/[man].md"}'),c={name:"man8/nscd.md"},d={class:"visually-hidden"};function h(e,a,l,m,g,p){return n(),t("div",null,[o("h1",d,r(e.$params.man),1),a[0]||(a[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nscd - name service cache daemon</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>nscd</strong> is a daemon that provides a cache for the most common name service requests. The default configuration file, <em>/etc/nscd.conf</em>, determines the behavior of the cache daemon. See <strong>nscd.conf</strong>(5).</p><p><strong>nscd</strong> provides caching for accesses of the <strong>passwd</strong>(5), <strong>group</strong>(5), <strong>hosts</strong>(5) <strong>services</strong>(5) and <em>netgroup</em> databases through standard libc interfaces, such as <strong>getpwnam</strong>(3), <strong>getpwuid</strong>(3), <strong>getgrnam</strong>(3), <strong>getgrgid</strong>(3), <strong>gethostbyname</strong>(3), and others.</p><p>There are two caches for each database: a positive one for items found, and a negative one for items not found. Each cache has a separate TTL (time-to-live) period for its data. Note that the shadow file is specifically not cached. <strong>getspnam</strong>(3) calls remain uncached as a result.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>--help</strong></dt><dd>will give you a list with all options and what they do.</dd></dl><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The daemon will try to watch for changes in configuration files appropriate for each database (e.g., <em>/etc/passwd</em> for the <em>passwd</em> database or <em>/etc/hosts</em> and <em>/etc/resolv.conf</em> for the <em>hosts</em> database), and flush the cache when these are changed. However, this will happen only after a short delay (unless the <strong>inotify</strong>(7) mechanism is available and glibc 2.9 or later is available), and this auto-detection does not cover configuration files required by nonstandard NSS modules, if any are specified in <em>/etc/nsswitch.conf</em>. In that case, you need to run the following command after changing the configuration file of the database so that <strong>nscd</strong> invalidates its cache:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nscd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">databas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nscd.conf</strong>(5), <strong>nsswitch.conf</strong>(5)</p>',13))])}const k=s(c,[["render",h]]);export{u as __pageData,k as default};
